CREATE TABLE IF NOT EXISTS masterdata_product_account_mapping (
    id                    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    product_category_id   BIGINT NOT NULL UNIQUE REFERENCES masterdata_product_category(id),
    inventory_account_id  BIGINT NOT NULL REFERENCES masterdata_coa(id),
    sales_account_id      BIGINT NOT NULL REFERENCES masterdata_coa(id),
    cogs_account_id       BIGINT NOT NULL REFERENCES masterdata_coa(id),
    return_account_id     BIGINT NOT NULL REFERENCES masterdata_coa(id),
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at            TIMESTAMPTZ NOT NULL DEFAULT now()
);
